// Blog inside the app. Guides are published as static pages under /blog/
// (generated by scripts/build-blog.mjs) so search engines can index them;
// the app links to those pages and redirects its old #/blog routes there.
import { CATEGORIES } from './data.js';
import * as D from './db.js';
import { POSTS, post, postsFor } from './blog/index.js';
import { postCard as card } from './blog/render.js';

const svcOf = p => D.service(p.service);
export const postCard = p => card(p, svcOf(p));

function leave(url) {
  location.replace(url);
  return { title: 'Blog', html: '<section class="shell section"><p class="muted">Opening the blog…</p></section>' };
}
export const blogIndex = (params, query) => leave('/blog/' + (query.get('s') ? '#' + encodeURIComponent(query.get('s')) : ''));
export const article = ({ slug }) => leave(post(slug) ? `/blog/${slug}/` : '/blog/');

// Guides for one service, used on service pages.
export const serviceGuides = serviceId => postsFor(serviceId).map(postCard).join('');
// A spread of guides for the home page: one per category.
export const featuredPosts = () => CATEGORIES.slice(0, 3).map(c => POSTS.find(p => svcOf(p)?.cat === c.id)).filter(Boolean);
